package io.github.diodeme.ji.agent.core;

import io.github.diodeme.ji.agent.AgentRuntime;
import io.github.diodeme.ji.agent.AgentSession;
import io.github.diodeme.ji.agent.RuntimeConfiguration;
import io.github.diodeme.ji.agent.SessionOptions;
import io.github.diodeme.ji.session.SessionSnapshot;
import java.util.Map;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.CompletionStage;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicBoolean;

final class CoreAgentRuntime implements AgentRuntime {
    private final RuntimeConfiguration configuration;
    private final boolean ownsExecutor;
    private final Map<String, CoreAgentSession> sessions = new ConcurrentHashMap<>();
    private final AtomicBoolean closed = new AtomicBoolean();

    CoreAgentRuntime(RuntimeConfiguration configuration, boolean ownsExecutor) {
        this.configuration = configuration;
        this.ownsExecutor = ownsExecutor;
    }

    @Override
    public AgentSession newSession(SessionOptions options) {
        requireOpen();
        String sessionId = configuration.idGenerator().next("session");
        SessionSnapshot snapshot = configuration.sessionStore().create(sessionId, options.model(), options.workingDirectory());
        return sessions.computeIfAbsent(sessionId, ignored -> new CoreAgentSession(configuration, snapshot));
    }

    @Override
    public AgentSession loadSession(String sessionId) {
        requireOpen();
        return sessions.computeIfAbsent(sessionId, ignored -> configuration.sessionStore().load(sessionId)
                .map(snapshot -> new CoreAgentSession(configuration, snapshot))
                .orElseThrow(() -> new IllegalArgumentException("session not found: " + sessionId)));
    }

    @Override
    public CompletionStage<Void> closeAsync() {
        if (!closed.compareAndSet(false, true)) return CompletableFuture.completedFuture(null);
        sessions.values().forEach(CoreAgentSession::close);
        configuration.provider().close();
        configuration.sessionStore().close();
        if (ownsExecutor) configuration.executor().close();
        return CompletableFuture.completedFuture(null);
    }

    private void requireOpen() {
        if (closed.get()) throw new IllegalStateException("runtime is closed");
    }
}
